import { Component, inject, input, signal, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TramiteService } from '../../../../../shared/services/tramite.service';
import { TipoDocumentoMaestroService } from '../../../../../shared/services/tipo-documento-maestro.service';
import { SolicitudService } from '../../../../../shared/services/solicitud.service';
import { ToastService } from '../../../../../shared/services/toast.service';
import { TramiteRequisito, SyncRequisitoPayload } from '../../../../../shared/models/tramite-requisito.model';
import { TipoDocumentoMaestro, PaginatedTiposDocumentoMaestro } from '../../../../../shared/models/tipo-documento-maestro.model';

@Component({
  selector: 'app-tramite-requisitos',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './tramite-requisitos.component.html',
})
export class TramiteRequisitosComponent implements OnInit {
  tramiteId = input.required<number>();

  private readonly tramiteService = inject(TramiteService);
  private readonly tipoDocumentoService = inject(TipoDocumentoMaestroService);
  private readonly solicitudService = inject(SolicitudService);
  private readonly toastService = inject(ToastService);

  municipios = signal<{ id: number; nombre: string }[]>([]);
  tiposDocumento = signal<TipoDocumentoMaestro[]>([]);
  selectedMunicipioId = signal<number | null>(null);
  requisitos = signal<TramiteRequisito[]>([]);
  newDocId = signal<number | null>(null);
  newIsObligatorio = signal<boolean>(true);
  loading = signal(false);
  saving = signal(false);

  ngOnInit(): void {
    this.loadMunicipios();
    this.loadTiposDocumento();
  }

  private loadMunicipios(): void {
    this.solicitudService.getMunicipios().subscribe((data) => {
      this.municipios.set(data);
      if (data.length > 0) {
        this.selectedMunicipioId.set(data[0].id);
        this.loadRequisitos(data[0].id);
      }
    });
  }

  private loadTiposDocumento(): void {
    this.tipoDocumentoService.getAll(1, 100).subscribe((res: PaginatedTiposDocumentoMaestro) => {
      this.tiposDocumento.set(res.data);
    });
  }

  onMunicipioChange(event: Event): void {
    const value = (event.target as HTMLSelectElement).value;
    if (value) {
      this.selectedMunicipioId.set(Number(value));
      this.loadRequisitos(Number(value));
    }
  }

  private loadRequisitos(municipioId: number): void {
    this.loading.set(true);
    this.tramiteService.getRequisitos(this.tramiteId(), municipioId).subscribe({
      next: (reqs: TramiteRequisito[]) => {
        this.requisitos.set(reqs);
        this.loading.set(false);
      },
      error: () => {
        this.toastService.error('Error al cargar requisitos');
        this.loading.set(false);
      }
    });
  }

  addRequisito(): void {
    const docId = this.newDocId();
    if (!docId) return;

    const currentReqs = this.requisitos();
    if (currentReqs.some(r => r.tipo_documento_maestro_id === Number(docId))) {
      this.toastService.warning('Este documento ya está agregado');
      return;
    }

    const maestro = this.tiposDocumento().find(t => t.id === Number(docId));
    if (!maestro) return;

    const aliasParaMunicipio = maestro.aliases?.find(a => a.municipioId === this.selectedMunicipioId());
    const nombreAMostrar = aliasParaMunicipio ? aliasParaMunicipio.alias : maestro.nombre;

    const newReq: TramiteRequisito = {
      id: 0,
      tramite_id: this.tramiteId(),
      municipio_id: this.selectedMunicipioId()!,
      tipo_documento_maestro_id: Number(docId),
      nombre: nombreAMostrar,
      nombre_original: maestro.nombre,
      es_obligatorio: this.newIsObligatorio()
    };

    this.requisitos.update(reqs => [...reqs, newReq]);
    this.newDocId.set(null);
  }

  removeRequisito(tipoId: number): void {
    this.requisitos.update(reqs => reqs.filter(r => r.tipo_documento_maestro_id !== tipoId));
  }

  saveRequisitos(): void {
    const municipioId = this.selectedMunicipioId();
    if (!municipioId) return;

    this.saving.set(true);
    
    const payload: SyncRequisitoPayload[] = this.requisitos().map(r => ({
      tipo_documento_maestro_id: r.tipo_documento_maestro_id,
      es_obligatorio: r.es_obligatorio
    }));

    this.tramiteService.syncRequisitos(this.tramiteId(), municipioId, payload).subscribe({
      next: (reqs: TramiteRequisito[]) => {
        this.requisitos.set(reqs);
        this.toastService.success('Requisitos guardados correctamente');
        this.saving.set(false);
      },
      error: () => {
        this.toastService.error('Error al guardar requisitos');
        this.saving.set(false);
      }
    });
  }
}
